  // NOUVEAU useEffect POUR CHARGER LES PUBLICATIONS
  useEffect(() => {
    const fetchPublications = async () => {
      setLoadingPublications(true);
      setErrorPublications(null); // Réinitialiser l'erreur

      try {
        // Utilisez la fonction apiRequest qui gère l'authentification et le rafraîchissement
        // Assurez-vous que cette URL correspond à votre endpoint de publications dans Django
        const response = await apiRequest(
          "http://127.0.0.1:8000/api/backend/api/publications/"
        );

        if (!response) {
          // apiRequest a déjà géré la déconnexion si le refresh token a échoué
          setErrorPublications(
            new Error(
              "Session expirée ou problème d'authentification. Veuillez vous reconnecter."
            )
          );
          // Une redirection vers la page de login pourrait être déclenchée ici aussi,
          // bien que apiRequest tente déjà de le faire.
          // navigate('/Connexion'); // Exemple si vous voulez forcer la redirection ici.
          return;
        }

        if (!response.ok) {
          const errorData = await response.json();
          // Vérifier si c'est une erreur 401 après la tentative de refresh
          if (response.status === 401) {
            setErrorPublications(
              new Error("Votre session a expiré. Veuillez vous reconnecter.")
            );
            // Rediriger vers la page de connexion
            // navigate('/Connexion'); // Décommentez si vous n'avez pas de gestion automatique dans apiRequest ou si vous voulez une double vérification.
          } else {
            throw new Error(
              `HTTP error! status: ${response.status} - ${JSON.stringify(
                errorData
              )}`
            );
          }
        } else {
          const data = await response.json();
          setPublications(data);
        }
      } catch (error) {
        setErrorPublications(error);
        console.error(
          "Erreur lors de la récupération des publications:",
          error
        );
      } finally {
        setLoadingPublications(false);
      }
    };

    // Charge les publications uniquement lorsque la section "veille" est active
    // ou si vous voulez les charger dès le montage, supprimez la condition
    if (activeSection === "veille") {
      fetchPublications();
    }
