                      value={profileData.email}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          email: e.target.value,
                        })
                      }
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Téléphone</label>
                    <input
                      type="tel"
                      className="form-control"
                      value={profileData.telephone}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          telephone: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>
                <button type="submit" className="btn btn-cta">
                  Enregistrer les modifications
                </button>
              </form>
            </div>
          </div>

          <div className="card mb-4">
            <div className="card-header">
              <h5 className="mb-0">Secteur d'activité</h5>
            </div>
            <div className="card-body">
              <div className="row">
                {secteursActivite.map((secteur, index) => (
                  <div key={index} className="col-md-6 mb-2">
                    <div className="form-check">
                      <input
                        className="form-check-input"
                        type="checkbox"
                        name="secteurActivite"
                        id={`secteur-${index}`}
                        value={secteur}
                        checked={profileData.secteurActivite === secteur}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            secteurActivite: e.target.value,
                          })
                        }
                      />
                      <label
                        className="form-check-label"
                        htmlFor={`secteur-${index}`}
                      >
                        {secteur}
                      </label>
                    </div>
                  </div>
                ))}
              </div>
              <div className="mt-3">
                <label className="form-label">Autre secteur</label>
                <input
                  type="text"
                  className="form-control"
                  placeholder="Précisez votre secteur d'activité..."
                />
              </div>
              <button className="btn btn-cta mt-3">
                Mettre à jour le secteur
              </button>
            </div>
          </div>

          <div className="card mb-4">
            <div className="card-header">
              <h5 className="mb-0">Domaines d'activité</h5>
            </div>
            <div className="card-body">
              <div className="row">
                {domainesActivite.map((domaine, index) => (
                  <div key={index} className="col-md-6 mb-2">
                    <div className="form-check">
                      <input
                        className="form-check-input"
                        type="checkbox"
                        id={`domaine-${index}`}
                      />
                      <label
                        className="form-check-label"
                        htmlFor={`domaine-${index}`}
                      >
                        {domaine}
                      </label>
                    </div>
                  </div>
                ))}
              </div>
              <div className="mt-3">
                <label className="form-label">Autre domaine</label>
                <input
                  type="text"
                  className="form-control"
                  placeholder="Précisez votre domaine d'activité..."
                />
              </div>
              <button className="btn btn-cta mt-3">
                Mettre à jour les domaines
              </button>
            </div>
          </div>
        </div>

        <div className="col-lg-4">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Changer le mot de passe</h5>
            </div>
            <div className="card-body">
              <form>
                <div className="mb-3">
                  <label className="form-label">Mot de passe actuel</label>
                  <input type="password" className="form-control" />
                </div>
                <div className="mb-3">
                  <label className="form-label">Nouveau mot de passe</label>
                  <input type="password" className="form-control" />
                </div>
                <div className="mb-3">
                  <label className="form-label">
                    Confirmer le nouveau mot de passe
                  </label>
                  <input type="password" className="form-control" />
                </div>
                <button type="submit" className="btn btn-cta w-100">
                  Mettre à jour le mot de passe
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderAddEntrepriseModal = () => (
    <div
      className={`modal fade ${showAddEntrepriseModal ? "show" : ""}`}
      style={{ display: showAddEntrepriseModal ? "block" : "none" }}
      tabIndex="-1"
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">Ajouter une entreprise</h5>
            <button
              type="button"
              className="btn-close"
              onClick={() => setShowAddEntrepriseModal(false)}
            ></button>
          </div>
          <form onSubmit={handleSubmitAddEntreprise}>
            <div className="modal-body">
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Nom de l'entreprise *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.nom}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        nom: e.target.value,
                      })
                    }
                    required
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">SIRET *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.siret}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        siret: e.target.value,
                      })
                    }
                  />
                </div>
              </div>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Téléphone</label>
                  <input
                    type="tel"
                    className="form-control"
                    value={addEntrepriseData.telephone}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        telephone: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Email</label>
                  <input
                    type="email"
                    className="form-control"
                    value={addEntrepriseData.email}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        email: e.target.value,
                      })
                    }
                  />
                </div>
              </div>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Nom du représentant</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.nomRepresentant}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        nomRepresentant: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Prénom du représentant</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.prenomRepresentant}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        prenomRepresentant: e.target.value,
                      })
                    }
                  />
                </div>
              </div>

              <div className="mb-3">
                <label className="form-label">Secteur d'activité</label>
                <select
                  className="form-select"
                  value={addEntrepriseData.secteurActivite}
                  onChange={(e) =>
                    setAddEntrepriseData({
                      ...addEntrepriseData,
                      secteurActivite: e.target.value,
                    })
                  }
                >
                  <option value="">Sélectionner un secteur</option>
                  {secteursActivite.map((secteur, index) => (
                    <option key={index} value={secteur}>
                      {secteur}
                    </option>
                  ))}
                </select>
              </div>

              <div className="mb-3">
                <label className="form-label">Domaines d'activité</label>
                <div className="row">
                  {domainesActivite.map((domaine, index) => (
                    <div key={index} className="col-md-6 mb-2">
                      <div className="form-check">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          id={`add-domaine-${index}`}
                          checked={addEntrepriseData.domainesActivite.includes(
                            domaine
                          )}
                          onChange={() => handleAddEntrepriseDomaine(domaine)}
                        />
                        <label
                          className="form-check-label"
                          htmlFor={`add-domaine-${index}`}
                        >
                          {domaine}
                        </label>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="modal-footer">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setShowAddEntrepriseModal(false)}
              >
                Annuler
              </button>
              <button type="submit" className="btn btn-cta">
                Ajouter l'entreprise
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );

  const renderModal = () => (
    <div
      className={`modal fade ${showModal ? "show" : ""}`}
      style={{ display: showModal ? "block" : "none" }}
      tabIndex="-1"
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">Aperçu du document</h5>
            <button
              type="button"
              className="btn-close"
              onClick={() => setShowModal(false)}
            ></button>
          </div>
          <div className="modal-body">
            {selectedDocument && (
              <div>
                <h6>{selectedDocument.titre}</h6>
                <p className="text-muted">
                  Date de publication : {selectedDocument.date}
                </p>
                <p className="text-muted">
                  Échéance : {selectedDocument.echeance}
                </p>
                <div
                  className="bg-light p-4 text-center"
                  style={{ height: "400px" }}
                >
                  <svg
                    width="64"
                    height="64"
                    fill="currentColor"
                    className="text-muted mb-3"
                    viewBox="0 0 16 16"
                  >
                    <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
                  </svg>
                  <p>Aperçu du document PDF</p>
                </div>
              </div>
            )}
          </div>
          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setShowModal(false)}
            >
              Fermer
            </button>
            <button type="button" className="btn btn-cta">
              Télécharger
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    switch (activeSection) {
      case "accueil":
        return renderAccueil();
      case "veille":
        return renderVeille();
      case "alertes":
        return renderAlertes();
      case "profil":
        return renderProfil();
      default:
        return renderAccueil();
    }
  };

  return (
    <>
      <style jsx>{`
        /* Styles CSS pour le Dashboard, si vous en avez */
        /* Exemple de base pour la mise en page */
        .dashboard-container {
          display: flex;
          min-height: 100vh;
          background-color: #f8f9fa; /* Couleur de fond légère */
        }

        .sidebar {
          width: 250px;
          background-color: #343a40; /* Couleur sombre pour la sidebar */
          color: white;
          padding: 20px;
          display: flex;
          flex-direction: column;
          position: sticky;
          top: 0;
          height: 100vh;
          transition: transform 0.3s ease-in-out;
          z-index: 1000; /* Assurez-vous qu'elle est au-dessus du contenu principal en mobile */
        }

        .sidebar.show {
          transform: translateX(0);
        }

        .sidebar-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 30px;
        }

        .sidebar-header h4 {
          margin: 0;
          color: #fff;
        }

        .btn-close-sidebar {
          background: none;
          border: none;
          color: white;
          font-size: 1.5rem;
        }

        .sidebar-select {
          background-color: #495057;
          color: white;
          border: 1px solid #6c757d;
        }

        .sidebar-select option {
          background-color: #343a40;
          color: white;
        }

        .btn-cta {
          background-color: #007bff; /* Couleur d'action principale */
          color: white;
          border: none;
          padding: 10px 15px;
          border-radius: 5px;
          transition: background-color 0.2s;
        }

        .btn-cta:hover {
          background-color: #0056b3;
        }

        .sidebar-nav {
          flex-grow: 1; /* Permet à la navigation de prendre l'espace disponible */
        }

        .sidebar-nav .nav-link {
          color: #adb5bd; /* Couleur des liens inactifs */
          padding: 10px 0;
          display: flex;
          align-items: center;
          text-decoration: none;
          transition: color 0.2s, background-color 0.2s;
          border-radius: 5px;
        }

        .sidebar-nav .nav-link:hover {
          color: white;
          background-color: #495057;
        }

        .sidebar-nav .nav-link.active {
          color: white;
          background-color: #007bff; /* Couleur du lien actif */
          font-weight: bold;
        }

        .sidebar-footer {
          margin-top: auto; /* Pousse le footer vers le bas */
          padding-top: 20px;
          border-top: 1px solid #495057;
        }

        .main-wrapper {
          flex-grow: 1;
          padding: 20px;
        }

        .content-header {
          margin-bottom: 30px;
        }

        .kpi-card {
          border-left: 5px solid #007bff; /* Bordure colorée pour les KPI */
        }

        .document-card {
          border: 1px solid #e0e0e0;
          text-align: center;
        }

        .modal {
          background-color: rgba(
            0,
            0,
            0,
            0.5
          ); /* Fond semi-transparent pour les modales */
        }

        /* Styles Mobile */
        @media (max-width: 767.98px) {
          .sidebar {
            position: fixed;
            left: 0;
            top: 0;
            height: 100%;
            transform: translateX(-100%); /* Masqué par défaut */
            box-shadow: 2px 0 5px rgba(0, 0, 0, 0.2);
          }

          .sidebar.show {
            transform: translateX(0);
          }

          .sidebar-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.5);
            z-index: 999; /* Moins que la sidebar, mais au-dessus du contenu */
            display: none;
          }

          .sidebar-overlay.show {
            display: block;
          }

          .mobile-header {
            background-color: #343a40;
            color: white;
            padding: 15px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            position: sticky;
            top: 0;
            z-index: 900;
          }

          .mobile-header .btn-menu {
            background: none;
            border: none;
            color: white;
            font-size: 1.5rem;
          }

          .main-wrapper {
            padding-top: 70px; /* Pour éviter que le contenu ne soit masqué par le header mobile */
          }
        }
      `}</style>

      <div className="dashboard-container">
        {renderMobileHeader()}
        {renderSidebar()}
        <div className="main-wrapper">{renderContent()}</div>
        {showModal && renderModal()}
        {showAddEntrepriseModal && renderAddEntrepriseModal()}
      </div>
    </>
  );
};

export default Dashboard;
